  page.evaluate("__blobMode='decode'");d=compare(page,seed);page.wait_for_function('__decodes.length===1');page.evaluate("__blobMode='normal'");d.locator('[name=compare-left]').select_option(seed['versions'][0]);page.wait_for_selector('[data-cmp-row]');assert 'ALPHA' in d.locator('[data-cmp-output]').inner_text();page.evaluate('__decodes.shift()()');page.wait_for_function('__decodes.length===1');page.evaluate('__decodes.shift()()');page.wait_for_timeout(80);d.locator('[name=compare-whitespace]').check();assert 'ALPHA' in d.locator('[data-cmp-output]').inner_text();assert 'BETA' not in d.locator('[data-cmp-output]').inner_text();ok('Late text decoding cannot poison a newer comparison or its option recalculation');close(page)
