  page.evaluate('(s)=>Civora.explorer.renameDialog([s.id])',seed);d=page.locator('.rename-dialog[open]');d.locator('[data-rename-name]').fill('First.txt');d.locator('[name=rename-reason]').fill('Delayed response test');d.locator('[data-rename-validate]').click();page.wait_for_function('__pending.length===1');d.locator('[data-rename-name]').fill('Second.txt');page.evaluate('__respond()');page.wait_for_timeout(80);assert d.locator('[type=submit]').is_disabled();assert d.locator('[data-rename-preview]').inner_text()=='';ok('Changed rename inputs invalidate an outstanding validation response')
