  d.locator('[data-rename-validate]').click();page.wait_for_function('__pending.length===1');page.evaluate('__respond()');page.wait_for_function('!document.querySelector(".rename-dialog [type=submit]").disabled');revision=page.evaluate('Civora.engine.state.revision');d.locator('[data-rename-name]').fill('Third.txt');d.locator('[data-rename-validate]').click();page.wait_for_function('__pending.length===1');close(page);page.evaluate('__respond()');page.wait_for_timeout(80);assert page.locator('.rename-dialog[open]').count()==0;assert page.evaluate('Civora.engine.state.revision')==revision;ok('Only exact responses validate; closing a pending rename never commits a write')
  page.evaluate('(s)=>Civora.explorer.renameDialog([s.id])',seed);page.evaluate("Civora.engine.actorId='not-this-account'");page.wait_for_function('!document.querySelector(".rename-dialog[open]")');assert not errors,errors;ok('Account switches close source-bearing rename forms even without a workspace event')
